/**
 * Trello Node - Version 1
 * Discriminator: resource=list, operation=get
 */


interface Credentials {
  trelloApi: CredentialReference;
  trelloOAuth1Api: CredentialReference;
}

/** Get the data of an attachment */
export type TrelloV1ListGetParams = {
  resource: 'list';
  operation: 'get';
  authentication?: 'apiKey' | 'oAuth1' | Expression<string>;
/**
 * The ID of the list to get
 */
    id: string | Expression<string>;
/**
 * Additional Fields
 * @default {}
 */
    additionalFields?: {
    /** Fields to return. Either "all" or a comma-separated list of fields.
     * @default all
     */
    fields?: string | Expression<string>;
  };
};

export type TrelloV1ListGetOutput = {
  closed?: boolean;
  datasource?: {
    filter?: boolean;
  };
  id?: string;
  idBoard?: string;
  name?: string;
  type?: null;
};

export type TrelloV1ListGetNode = {
  type: 'n8n-nodes-base.trello';
  version: 1;
  config: NodeConfig<TrelloV1ListGetParams> & { credentials?: Credentials };
  output?: Items<TrelloV1ListGetOutput>;
};